bounded_host_request.command:
set -euo pipefail
name=gace-createvdobot-videobot-poll-1
test "$(docker inspect -f '{{.State.Running}}' "$name" 2>/dev/null)" = true || { echo 'STK_CATALOG_BOT_DOWN';exit 61; }
docker exec -i "$name" node --input-type=module - <<'NODE'
import pg from 'pg';
import {readFileSync} from 'node:fs';
import {createCreatorTelegramFetch} from './src/runtime/creatorEgress.mjs';
import {createTelegramBotApi} from './src/telegram/botApi.mjs';
const e=process.env;
const productId='sp_76f23430d1c29ca355960a95';
const oldMessageId=4664,chatId=-1002373696859,threadId=4640;
const pool=new pg.Pool({host:e.VIDEOBOT_DB_HOST,database:e.VIDEOBOT_DB_NAME,user:e.VIDEOBOT_DB_USER,password:readFileSync(e.VIDEOBOT_DB_PASSWORD_FILE,'utf8').trim(),max:1,connectionTimeoutMillis:7000});
const outgoing=createCreatorTelegramFetch(globalThis.fetch);
try{
 const got=await pool.query("SELECT p.product_id,p.seller_user_id,p.title,p.pack_name,p.kind,p.items,p.price_stars,p.status AS product_status,p.management_fee_bps,p.fee_policy_id,p.fee_terms_accepted_at,t.telegram_message_id,t.status AS post_status,t.chat_id,t.message_thread_id FROM videobot_sticker_products p JOIN videobot_sticker_topic_posts t ON t.product_id=p.product_id WHERE p.product_id=$1",[productId]);
 if(got.rowCount!==1)throw Error('STK_CATALOG_PRODUCT_NOT_UNIQUE');
 const p=got.rows[0],items=typeof p.items==='string'?JSON.parse(p.items):p.items;
 if(p.product_status!=='published'||p.post_status!=='sent'||Number(p.telegram_message_id)!==oldMessageId||
 Number(p.chat_id)!==chatId||Number(p.message_thread_id)!==threadId||Number(p.price_stars)!==50||
 Number(p.management_fee_bps)!==3000||p.fee_policy_id!=='sticker-admin-30-20261113'||!p.fee_terms_accepted_at||
 !Array.isArray(items)||items.length<1||items.length>200||
 typeof p.title!=='string'||!p.title||p.title.length>64||
 !['regular','custom_emoji'].includes(p.kind)||typeof p.pack_name!=='string'||!/^[A-Za-z0-9_]{1,64}$/.test(p.pack_name))
 throw Error('STK_CATALOG_EXISTING_STATE_MISMATCH');
 const historical=await pool.query("SELECT (SELECT COUNT(*)::int FROM videobot_sticker_orders WHERE product_id=$1) AS orders,(SELECT COUNT(*)::int FROM videobot_sticker_paid_photo_sales WHERE product_id=$1) AS paid",[productId]);
 if(historical.rows[0].orders!==0||historical.rows[0].paid!==0)throw Error('STK_CATALOG_EXISTING_ORDERS_REQUIRES_RECONCILE');
 const token=readFileSync(e.VIDEOBOT_TELEGRAM_TOKEN_FILE,'utf8').trim();
 const api=createTelegramBotApi({token,fetchImpl:outgoing.fetch,timeoutMs:25000});
 const bot=await api('getMe',{});
 if(bot?.is_bot!==true||String(bot.username).toLowerCase()!=='createvdobot')throw Error('STK_CATALOG_BOT_IDENTITY_INVALID');
 const pin=JSON.parse(readFileSync('/var/lib/videobot/sticker-entry/group2373696859_thread4640.json','utf8'));
 if(pin.status!=='pinned_ack'||Number(pin.chat_id)!==chatId||Number(pin.thread_id)!==threadId||
 Number(pin.message_id)===oldMessageId||Number(pin.bot_id)!==bot.id)
 throw Error('STK_CATALOG_PIN_RECEIPT_CHANGED');
 const member=await api('getChatMember',{chat_id:chatId,user_id:bot.id});
 if(!['administrator','creator'].includes(member?.status))throw Error('STK_CATALOG_NO_BOT_ACCESS');
 const set=await api('getStickerSet',{name:p.pack_name});
 if(set?.name!==p.pack_name||!Array.isArray(set.stickers)||set.stickers.length<1)
 throw Error('STK_CATALOG_TELEGRAM_PACK_NOT_VERIFIED');
 const text='🎨 '+p.title+'\n⭐ 50 Stars · '+items.length+'個';
 const claim=await pool.query("UPDATE videobot_sticker_topic_posts SET status='sending',updated_at=NOW() WHERE product_id=$1 AND status='sent' AND telegram_message_id=$2 AND chat_id=$3 AND message_thread_id=$4 RETURNING product_id",[productId,oldMessageId,chatId,threadId]);
 if(claim.rowCount!==1)throw Error('STK_CATALOG_ALREADY_CHANGED');
 // One authoritative Telegram send only, after durable claim. Never auto-retry an unknown send.
 const sent=await api('sendMessage',{chat_id:chatId,message_thread_id:threadId,text,reply_markup:{inline_keyboard:[[{text:'📦 パックの中身を見る・Stars購入',url:'https://t.me/CreateVdobot?start=buy_'+productId}]]}});
 if(!Number.isSafeInteger(sent?.message_id)||sent.message_id<=0||
 sent?.chat?.id!==chatId||sent?.message_thread_id!==threadId||
 sent?.is_topic_message!==true||sent?.from?.id!==bot.id)
 throw Error('STK_CATALOG_NEW_POST_UNVERIFIED');
 const record=await pool.query("UPDATE videobot_sticker_topic_posts SET telegram_message_id=$2,display_text=$3,status='sent',updated_at=NOW() WHERE product_id=$1 AND telegram_message_id=$4 AND status='sending' AND chat_id=$5 AND message_thread_id=$6 RETURNING telegram_message_id",[productId,sent.message_id,text,oldMessageId,chatId,threadId]);
 if(record.rowCount!==1)throw Error('STK_CATALOG_NEW_POST_RECEIPT_UNKNOWN');
 console.log('STK_CATALOG_NEW_POST=PASS');
 console.log('STK_CATALOG_NEW_MESSAGE_ID='+sent.message_id);
 const removed=await api('deleteMessage',{chat_id:chatId,message_id:oldMessageId});
 if(removed!==true)throw Error('STK_CATALOG_OLD_POST_DELETE_UNKNOWN');
 console.log('STK_CATALOG_OLD_IMAGE_REMOVED=PASS');
 console.log('STK_CATALOG_SAME_PRODUCT_AND_TOPIC=PASS');
}finally{await outgoing.close();await pool.end();}
NODE
